"""Заметки перекупа и мастера по поколениям моделей.

Собрано по типичным жалобам владельцев (форумы моделей, отзывные кампании NHTSA, TSB) и практике
перепродажи в Хьюстоне. Цены ремонта — независимый сервис в Хьюстоне, ориентир, не смета.
note(lot) -> строка или None. Пробег lot['o'] в милях."""
import re

K = []  # (марка, regex модели, год от, год до, текст, [(пробег от, добавка)])


def E(mk, md, y0, y1, txt, hi=()):
    K.append((mk.lower(), re.compile(md, re.I), y0, y1, txt, list(hi)))


