def note(l):
    mk, md, y = (l.get('mk') or '').lower(), (l.get('md') or '').strip(), int(l.get('y') or 0)
    o = int(l.get('o') or 0)
    for kmk, rx, y0, y1, txt, hi in K:
        if not re.fullmatch(kmk, mk) and not any(mk == p for p in kmk.split('|')):
            continue
        if not rx.search(md) or not (y0 <= y <= y1):
            continue
        add = [t for m, t in hi if o >= m]
        return txt + (' ' + add[-1] if add else '')
    return None


if __name__ == '__main__':
    import glob, json, collections
    miss = collections.Counter(); hit = 0; tot = 0
    for f in sorted(glob.glob('data/20*.json')):
        for l in json.load(open(f))['lots']:
            tot += 1
            if note(l): hit += 1
            else: miss[(l['mk'], l['md'], l['y'])] += 1
    print(hit, tot)
    print(miss.most_common(60))
